module cloud_compare(\n    input clk,\n    input rst_n,\n    input [3:0] n,\n    input [3:0] m,\n    input [5:0] garry_triangles [0:7][0:2][0:1],\n    input [5:0] jerry_triangles [0:7][0:2][0:1],\n    output reg same,\n    output reg done\n);\n    localparam [3:0]\n        INIT         = 4'd0,\n        GARRY_SETUP  = 4'd1,\n        GARRY_RASTER = 4'd2,\n        GARRY_NEXT   = 4'd3,\n        JERRY_SETUP  = 4'd4,\n        JERRY_RASTER = 4'd5,\n        JERRY_NEXT   = 4'd6,\n        COMPARE      = 4'd7,\n        FINISH       = 4'd8;\n\n    reg [3:0] state, next_state;\n    reg [3:0] garry_idx, jerry_idx;\n    reg [3:0] x, y;\n    reg [7:0] cycle_count;\n    reg [15:0] garry_grid [0:15];\n    reg [15:0] jerry_grid [0:15];\n    reg reverse_winding;\n    wire [5:0] A = garry_triangles[garry_idx][0][0];\n    wire [5:0] B = garry_triangles[garry_idx][1][0];\n    wire [5:0] C = garry_triangles[garry_idx][2][0];\n    wire [5:0] D = garry_triangles[garry_idx][0][1];\n    wire [5:0] E = garry_triangles[garry_idx][1][1];\n    wire [5:0] F = garry_triangles[garry_idx][2][1];\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= INIT;\n            same <= 1'b0;\n            done <= 1'b0;\n            garry_idx <= 4'd0;\n            jerry_idx <= 4'd0;\n            x <= 4'd0;\n            y <= 4'd0;\n            cycle_count <= 8'd0;\n            for (i = 0; i < 16; i = i + 1) begin\n                garry_grid[i] <= 16'd0;\n                jerry_grid[i] <= 16'd0;\n            end\n            reverse_winding <= 1'b0;\n        end else begin\n            case (state)\n                INIT: begin\n                    done <= 1'b0;\n                    cycle_count <= cycle_count + 8'd1;\n                    state <= GARRY_SETUP;\n                end\n\n                GARRY_SETUP: begin\n                    x <= 4'd0;\n                    y <= 4'd0;\n                    if (garry_idx < n) begin\n                        reverse_winding <= ((B - A) * (F - D) - (E - D) * (C - A)) < 0;\n                        state <= GARRY_RASTER;\n                    end else begin\n                        jerry_idx <= 4'd0;\n                        state <= JERRY_SETUP;\n                    end\n                end\n\n                GARRY_RASTER: begin\n                    if (((B - A) * ((y<<2) - D) - ((x<<2) - A) * (E - D) >= reverse_winding) &&\n                        ((C - B) * ((y<<2) - E) - ((x<<2) - B) * (F - E) >= reverse_winding) &&\n                        ((A - C) * ((y<<2) - F) - ((x<<2) - C) * (D - F) >= reverse_winding))\n                        garry_grid[y] <= garry_grid[y] | (1 << x);\n\n                    if (x == 4'd15) begin\n                        x <= 4'd0;\n                        if (y == 4'd15) begin\n                            y <= 4'd0;\n                            garry_idx <= garry_idx + 4'd1;\n                            state <= GARRY_SETUP;\n                        end else begin\n                            y <= y + 4'd1;\n                        end\n                    end else begin\n                        x <= x + 4'd1;\n                    end\n\n                    if (cycle_count > 8'd128) state <= FINISH;\n                end\n\n                JERRY_SETUP: begin\n                    x <= 4'd0;\n                    y <= 4'd0;\n                    if (jerry_idx < m) begin\n                        reverse_winding <= ((\n                        jerry_triangles[jerry_idx][1][0] - jerry_triangles[jerry_idx][0][0]) *\n                        (jerry_triangles[jerry_idx][2][1] - jerry_triangles[jerry_idx][0][1]) -\n                        (jerry_triangles[jerry_idx][1][1] - jerry_triangles[jerry_idx][0][1]) *\n                        (jerry_triangles[jerry_idx][2][0] - jerry_triangles[jerry_idx][0][0])) < 0;\n                        state <= JERRY_RASTER;\n                    end else begin\n                        state <= COMPARE;\n                    end\n                end\n\n                JERRY_RASTER: begin\n                    if (((\n                        jerry_triangles[jerry_idx][1][0] - jerry_triangles[jerry_idx][0][0]) *\n                        ((y<<2) - jerry_triangles[jerry_idx][0][1]) -\n                        ((x<<2) - jerry_triangles[jerry_idx][0][0]) *\n                        (jerry_triangles[jerry_idx][1][1] - jerry_triangles[jerry_idx][0][1]) >= reverse_winding) &&\n                        ((jerry_triangles[jerry_idx][2][0] - jerry_triangles[jerry_idx][1][0]) *\n                        ((y<<2) - jerry_triangles[jerry_idx][1][1]) -\n                        ((x<<2) - jerry_triangles[jerry_idx][1][0]) *\n                        (jerry_triangles[jerry_idx][2][1] - jerry_triangles[jerry_idx][1][1]) >= reverse_winding) &&\n                        ((jerry_triangles[jerry_idx][0][0] - jerry_triangles[jerry_idx][2][0]) *\n                        ((y<<2) - jerry_triangles[jerry_idx][2][1]) -\n                        ((x<<2) - jerry_triangles[jerry_idx][2][0]) *\n                        (jerry_triangles[jerry_idx][0][1] - jerry_triangles[jerry_idx][2][1]) >= reverse_winding))\n                        jerry_grid[y] <= jerry_grid[y] | (1 << x);\n\n                    if (x == 4'd15) begin\n                        x <= 4'd0;\n                        if (y == 4'd15) begin\n                            y <= 4'd0;\n                            jerry_idx <= jerry_idx + 4'd1;\n                            state <= JERRY_SETUP;\n                        end else begin\n                            y <= y + 4'd1;\n                        end\n                    end else begin\n                        x <= x + 4'd1;\n                    end\n\n                    if (cycle_count > 8'd200) state <= FINISH;\n                end\n\n                COMPARE: begin\n                    same <= 1'b1;\n                    for (i = 0; i < 16; i = i + 1) begin\n                        if (garry_grid[i] !== jerry_grid[i]) same <= 1'b0;\n                    end\n                    state <= FINISH;\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= INIT;\n                end\n\n                default: state <= INIT;\n            endcase\n        end\n    end\nendmodule